import { ArrowRight, Sparkles } from 'lucide-react'
import Link from "next/link"

export default function Home() {
  return (
    <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background via-background to-muted/20 p-4">
      <div className="max-w-2xl w-full text-center space-y-8">
        {/* Logo/Badge */}
        <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-primary/5 border border-primary/10">
          <Sparkles className="h-4 w-4 text-primary" />
          <span className="text-sm font-medium text-foreground">AI-LaunchPad</span>
        </div>

        {/* Main Content */}
        <div className="space-y-4">
          <h1 className="text-4xl md:text-5xl font-bold tracking-tight text-balance">
            恭喜!环境已就绪
          </h1>
          <p className="text-lg md:text-xl text-muted-foreground text-balance leading-relaxed">
            您的网页开发环境已经配置完成。现在,是时候将您的想法变为现实,打造出色的产品了。
          </p>
        </div>

        <div className="pt-4">
          <p className="text-sm text-muted-foreground">
            您可以开始编辑 <code className="px-2 py-1 rounded bg-muted font-mono text-xs">app/page.tsx</code> 来构建您的应用
          </p>
        </div>

        {/* Footer Link */}
        <div className="pt-8">
          <Link 
            href="https://ai-launchpad.net" 
            target="_blank"
            rel="noopener noreferrer"
            className="text-sm text-muted-foreground hover:text-foreground transition-colors inline-flex items-center gap-1"
          >
            访问 AI-LaunchPad 官网
            <ArrowRight className="h-3 w-3" />
          </Link>
        </div>
      </div>
    </main>
  )
}
